            { t = "Dew still on the clover, so I wait. A bee with wet feet is a cross bee. Read me through the wait?", when = { hour = "morning" } },
            { t = "First trip of the day is the scouting trip. I scouted you. Report: favourable.", when = { hour = "morning" } },
            { t = "Midday, peak flying. Fifty flowers a trip, a dozen trips, and a hello for you in between. Onwards.", when = { hour = "day" } },
            { t = "Noon. The sun stands nearly overhead, which makes dancing directions awkward. I shall simply point: there, your book.", when = { hour = "day" } },
