            { t = "Evening count. Blossoms: plenty. Trips: enough. Pages: that column is yours, and any number suits.", when = { hour = "golden" } },
            { t = "Dark now. We are all indoors, fanning the nectar down to honey. You could do the same with a chapter.", when = { hour = "night" } },
            { t = "Bees do sleep, you know. I am putting that off. Your lamp looks like a late flower.", when = { hour = "night" } },
            { t = "Dandelions first, then the blossom, then everything at once. Spring is all beginnings. Pick one and start.", when = { season = "spring" } },
