    beats = {
        { id = "cell", at = 15, title = "The cell",
            text = "I was raised in a six-sided room of wax, one of thousands in a row, all alike. My first job on stepping out was to clean my own cell. Nobody told me to. I simply knew, and I have been tidying ever since." },
        { id = "nursery", at = 40, title = "The nursery",
            text = "Then I fed the young. A thousand small visits a day, each a few seconds long. I thought the job was dull. I see now where I learned to count, and to keep coming back." },
        { id = "wax", at = 80, title = "Wax",
            text = "Next I built comb. We hang in chains, leg hooked to leg, and the wax comes out of us in small flakes. I held on to a sister whose face I never saw. I still remember the weight of her." },
        { id = "door", at = 140, title = "The door",
            text = "Before I was allowed to fly, I stood guard at the hive door and smelled everyone who came in. All day I watched the foragers leave empty and return with gold on their legs. I wanted that badly." },
        { id = "first_flight", at = 220, title = "The first flight",
            text = "On my first flight I never left sight of home. I hovered backwards, facing the hive, learning the shape of every twig around the door. That is our way: before you go far, learn the road back." },
        { id = "dance", at = 320, title = "The dance",
            text = "An old forager danced for me in the dark of the comb: this angle from the sun, this far. I followed, flew out, and the lime tree stood exactly where she said. I had not known a body could say a place." },
        { id = "swarm", at = 450, title = "The swarm",
            text = "One May morning half of us poured out with the old queen and hung in a ball on a branch. No home, no honey, no plan. I was sent as a scout. My whole task was to find us somewhere to live." },
        { id = "hollow", at = 600, title = "The hollow",
            text = "I found a hollow in an apple tree: dry, the right size, facing south. I danced for that hollow for two days. The others chose a chimney three fields off, and I went with them. The apple tree still comes to mind." },
        { id = "caught", at = 800, title = "Caught out",
            text = "Late one day a storm caught me far from the hive, too wet to fly. I crawled into a foxglove bell and spent the night there alone, which a bee never is. I learned that I could be. I did not much like the lesson." },
        { id = "garden", at = 1050, title = "A new line",
            text = "Next morning I flew a line I had never flown and came down here. Lavender, clover, and somebody sitting still with pages. I worked the lavender and watched you. You gathered all afternoon and carried nothing away. I was baffled." },
        { id = "honey", at = 1400, title = "What you make",
            text = "I have worked out what you do. You visit a page the way I visit a flower, {total} of them by now, and something sweet is stored where nobody sees. I have made honey all my life. I know the trade when I meet another maker." },
        { id = "home", at = 1800, title = "The dance for here",
            text = "Nobody followed my dance for the apple tree. So here is my best one, and you are the only one watching. This angle from the sun. This far. A chair, a lamp, a reader. I have flown to ten thousand flowers. This is the one place I dance as home." },
    },
}
